python -c "
import json
W=json.load(open('captions.json',encoding='utf8'))
for w in W[18:45]: print(w['startMs'], w['endMs'], repr(w['text']))
print('gaps:')
for i in range(1,45):
    g=W[i]['startMs']-W[i-1]['endMs']
    if g>=200: print(round(g), 'before', W[i]['text'].strip(), 'at', W[i]['startMs'])
"
